command:
// ==========================================
// LUNAS WIRKUNG: GEISTERDIENER (ZERZAL)
// ==========================================

(async function () {
    const macroUuid = this?.uuid || game.macros.getName("Geisterdiener")?.uuid || null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt =
    !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
    !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
    !globalThis.DSK?.Empfaenger?.Besitzer ||
    !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
    !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
    !globalThis.DSK?.GabenUI?.GMMakroButton ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);
    if (!fwMacro) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
    await fwMacro.execute();
    await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;

if (
    !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
    !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
    !DSK_FW?.Empfaenger?.Besitzer ||
    !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
    !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
    !DSK_FW?.GabenUI?.GMMakroButton ||
    !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
    !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!");

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Geisterdiener";
    const vollerName = "Geisterdiener (Zerzal)";
    const ahne = "Zerzal";
    const radiusSchritt = 16;
    const flagKey = "pendingGeisterdienerZerzal";
    const quellFlag = "geisterdienerQuelle";
    const basisRechteFlag = "geisterdienerBasisRechte";
    const sitzungenFlag = "geisterdienerSitzungen";
    const symbolPfad = DSK_FW.Symbol(ahne);

    const basisBeschreibung =
        `Eine durch Seelenbindung an einen Schädel gebundene Seele materialisiert sich. ` +
        `Sie ist physisch greifbar und verletzlich.`;

    DSK_FW.EffektEnde.Register(
        "geisterdienerZerzal",
        vollerName,
        "Der materialisierte Leib der Seele verschwindet und sie kehrt friedlich in den Schädel zurück."
    );

    // +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

    const istAktiverGM = () => {
        const gm = game.users.find(user => user.isGM && user.active);
        return gm ? game.user.id === gm.id : game.user.isGM;
    };

    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) {
            await actor.unsetFlag("world", "letzteGabenQS");
        }
    };

    const ladeActor = async uuid => {
        if (!uuid) return null;

        try {
            const doc = await fromUuid(uuid);
            return doc?.documentName === "Token" ? doc.actor : doc || null;
        } catch (error) {
            console.warn("Geisterdiener: Akteur konnte nicht geladen werden.", { uuid, error });
            return null;
        }
    };

    const ladeToken = async ({ tokenUuid = null, tokenId = null, sceneId = null } = {}) => {
        if (tokenUuid) {
            try {
                const doc = await fromUuid(tokenUuid);
                if (doc?.documentName === "Token") return doc;
            } catch (error) {
                console.warn("Geisterdiener: Token-UUID konnte nicht geladen werden.", { tokenUuid, error });
            }
        }

        return (game.scenes.get(sceneId) || canvas.scene)?.tokens.get(tokenId) || null;
    };

    const findeHaupteffekt = (actor, sessionId = null) =>
        actor?.effects?.find(effect =>
            (effect.name || effect.label || "") === vollerName &&
            effect.getFlag("dsk", "isGeisterdiener") === true &&
            (!sessionId || effect.getFlag("dsk", "sessionId") === sessionId)
        ) || null;

    const tokenMitte = tokenDokument => ({
        x: Number(tokenDokument?.x || 0) + Number(tokenDokument?.width || 1) * canvas.grid.size / 2,
        y: Number(tokenDokument?.y || 0) + Number(tokenDokument?.height || 1) * canvas.grid.size / 2
    });

    const entfernungInSchritt = (a, b) =>
        (Math.hypot(Number(a.x) - Number(b.x), Number(a.y) - Number(b.y)) / canvas.grid.size) *
        (Number(canvas.scene?.grid?.distance) || 1);

    const warnEmpfaenger = actor => Array.from(new Set([
        ...game.users.filter(user => user.isGM && user.active).map(user => user.id),
        ...Object.entries(actor?.ownership || {})
            .filter(([id, level]) =>
                id !== "default" &&
                Number(level) === CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER &&
                game.users.get(id)
            )
            .map(([id]) => id)
    ]));

    // +++ 4 - REICHWEITENWARNUNG ++++++++++++++++++++++++++++++

    const aktualisiereReichweitenWarnung = async ({ effekt, dienerToken, casterActor }) => {
        if (!effekt || !dienerToken || !casterActor || !istAktiverGM()) return;

        let schaedelMitte = null;

        if (effekt.getFlag("dsk", "modus") === "ort") {
            const scene = game.scenes.get(effekt.getFlag("dsk", "sceneId")) || canvas.scene;
            const template = scene?.templates.get(effekt.getFlag("dsk", "schaedelTemplateId"));

            if (template) {
                schaedelMitte = { x: Number(template.x), y: Number(template.y) };
            }
        } else {
            const casterToken = await ladeToken({
                tokenUuid: effekt.getFlag("dsk", "casterTokenUuid"),
                tokenId: effekt.getFlag("dsk", "casterTokenId"),
                sceneId: effekt.getFlag("dsk", "sceneId")
            });

            if (casterToken) schaedelMitte = tokenMitte(casterToken);
        }

        if (!schaedelMitte) return;

        const entfernung = entfernungInSchritt(tokenMitte(dienerToken), schaedelMitte);
        const warnMessageId = effekt.getFlag("dsk", "reichweitenWarnungMessageId");

        if (entfernung > radiusSchritt) {
            if (warnMessageId && game.messages.get(warnMessageId)) return;

            const warnMessage = await ChatMessage.create({
                speaker: { alias: "System" },
                whisper: warnEmpfaenger(casterActor),

                content: `
                    <div style="font-family:'Signika',sans-serif;">
                        ${DSK_FW.UI.Header("Geisterdiener - Bindungsreichweite", symbolPfad)}

                        <div class="dskbox2" style="margin-top:10px;">
                            <p style="text-align:center;color:#B30000;font-weight:bold;">
                                Außerhalb der Bindungsreichweite
                            </p>

                            <p>
                                <b>${dienerToken.name}</b> ist weiter als
                                <b>${radiusSchritt} Schritt</b> vom gebundenen Schädel entfernt.
                            </p>

                            <p style="margin-bottom:0;font-size:.9em;">
                                Diese Warnung verschwindet automatisch, sobald der
                                Geisterdiener wieder innerhalb der Reichweite ist.
                            </p>
                        </div>
                    </div>
                `
            });

            if (warnMessage) {
                await effekt.setFlag(
                    "dsk",
                    "reichweitenWarnungMessageId",
                    warnMessage.id
                );
            }

            return;
        }

        if (warnMessageId) {
            const warnMessage = game.messages.get(warnMessageId);
            if (warnMessage) await warnMessage.delete().catch(() => {});

            await effekt
                .unsetFlag("dsk", "reichweitenWarnungMessageId")
                .catch(() => {});
        }
    };

    // +++ 5 - DIENER AUS AHNENGABE LESEN ++++++++++++++++++++++

    const findeDienerAusAhnengabe = async actor => {
        let text = "";

        const item = actor.items.find(item =>
            ["ahnengabe", "specialability"].includes(item.type) &&
            String(item.name || "").toLowerCase().includes("geisterdiener")
        );

        if (item) {
            text =
                `${item.system?.description?.value || ""} ` +
                `${item.system?.gminfo || item.system?.gmnotes || ""}`;
        }

        if (!text.trim()) {
            text = String(
                actor.system?.details?.notes?.value ||
                actor.system?.biography?.value ||
                ""
            );
        }

        const uuidRegex = /@UUID\[([^\]]+)\](?:\{([^}]+)\})?/g;
        const diener = [];
        let match;

        while ((match = uuidRegex.exec(text)) !== null) {
            const uuid = match[1];
            if (!uuid.includes("Actor")) continue;

            let name = match[2] || "";

            if (!name) {
                try {
                    name = (await fromUuid(uuid))?.name || "Unbekannter Geist";
                } catch {
                    name = "Geisterdiener";
                }
            }

            diener.push({ uuid, name });
        }

        return diener;
    };

    // +++ 6 - DIENER LADEN / IMPORTIEREN ++++++++++++++++++++++

    const findeImportiertenDiener = uuid =>
        game.actors.find(actor =>
            actor.getFlag("dsk", quellFlag) === uuid ||
            actor.getFlag("core", "sourceId") === uuid
        ) || null;

    const ladeOderImportiereDiener = async ({ sourceUuid, sourceName }) => {
        let source = sourceUuid
            ? await fromUuid(sourceUuid).catch(() => null)
            : null;

        if (!source && sourceName) {
            source =
                game.actors.find(actor =>
                    String(actor.name || "").toLowerCase() ===
                    String(sourceName).toLowerCase()
                ) || null;
        }

        if (!source) {
            throw new Error("Der ausgewählte Geisterdiener wurde nicht gefunden.");
        }

        if (!sourceUuid?.startsWith("Compendium.")) return source;

        let actor = findeImportiertenDiener(sourceUuid);
        if (actor) return actor;

        const data = source.toObject();
        delete data._id;
        delete data.folder;
        delete data.sort;

        foundry.utils.setProperty(data, `flags.dsk.${quellFlag}`, sourceUuid);
        foundry.utils.setProperty(data, "flags.core.sourceId", sourceUuid);

        actor = await Actor.create(data, { renderSheet: false });

        if (!actor) {
            throw new Error("Der Geisterdiener konnte nicht importiert werden.");
        }

        return actor;
    };

    // +++ 7 - RECHTEVERWALTUNG ++++++++++++++++++++++++++++++++

    const baueRechte = ({ basis = {}, sitzungen = {} }) => {
        const ownership = foundry.utils.deepClone(basis);

        for (const sitzung of Object.values(sitzungen)) {
            for (const userId of sitzung?.userIds || []) {
                if (!game.users.get(userId)) continue;
                ownership[userId] = CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER;
            }
        }

        return ownership;
    };

    const fuegeRechteHinzu = async ({ actor, sessionId, userIds }) => {
        let sitzungen = foundry.utils.deepClone(
            actor.getFlag("dsk", sitzungenFlag) || {}
        );

        let basis = actor.getFlag("dsk", basisRechteFlag);

        if (!basis || !Object.keys(sitzungen).length) {
            basis = foundry.utils.deepClone(actor.ownership || {});
        }

        sitzungen[sessionId] = {
            userIds: [...new Set(userIds)],
            erstellt: Date.now()
        };

        await actor.update({
            ownership: baueRechte({ basis, sitzungen }),
            [`flags.dsk.${basisRechteFlag}`]: basis,
            [`flags.dsk.${sitzungenFlag}`]: sitzungen
        });
    };

    const entferneRechte = async ({ actor, sessionId }) => {
        const sitzungen = foundry.utils.deepClone(
            actor.getFlag("dsk", sitzungenFlag) || {}
        );

        const basis = actor.getFlag("dsk", basisRechteFlag);
        delete sitzungen[sessionId];

        if (!Object.keys(sitzungen).length) {
            await actor.update({
                ownership: foundry.utils.deepClone(
                    basis || actor.ownership || {}
                )
            });

            if (actor.getFlag("dsk", basisRechteFlag) !== undefined) {
                await actor.unsetFlag("dsk", basisRechteFlag);
            }

            if (actor.getFlag("dsk", sitzungenFlag) !== undefined) {
                await actor.unsetFlag("dsk", sitzungenFlag);
            }
        } else {
            await actor.update({
                ownership: baueRechte({
                    basis: basis || actor.ownership || {},
                    sitzungen
                }),
                [`flags.dsk.${sitzungenFlag}`]: sitzungen
            });
        }
    };

    // +++ 8 - SCHÄDELMODUS ++++++++++++++++++++++++++++++++++++

    const frageSchaedelmodus = () =>
        foundry.applications.api.DialogV2.wait({
            window: { title: "Standort des Schädels" },
            position: { width: 430 },

            content: `
                <form>
                    ${DSK_FW.UI.Header(vollerName, symbolPfad)}

                    <div class="dskbox2" style="margin-top:10px;">
                        <p style="text-align:center;margin:0;">
                            Wo befindet sich der gebundene Schädel?
                        </p>
                    </div>
                </form>
            `,

            buttons: [
                {
                    action: "selbst",
                    label: "Bei mir",
                    icon: "fas fa-user",
                    default: true,
                    callback: () => "selbst"
                },
                {
                    action: "ort",
                    label: "An einem Ort",
                    icon: "fas fa-map-marker-alt",
                    callback: () => "ort"
                },
                {
                    action: "cancel",
                    label: "Abbrechen",
                    icon: "fas fa-times",
                    callback: () => null
                }
            ],

            rejectClose: false
        });

    const bestaetigeSchaedelposition = () =>
        foundry.applications.api.DialogV2.wait({
            window: { title: "Schädel platzieren" },
            position: { width: 430 },

            content: `
                <div style="font-family:'Signika',sans-serif;">
                    ${DSK_FW.UI.Header(vollerName, symbolPfad)}

                    <div class="dskbox2" style="margin-top:10px;">
                        <p style="font-size:.95em;line-height:1.35;">
                            Verschiebe den kleinen Schädelkreis auf die gewünschte
                            Position der Karte.

                            <br><br>

                            Klicke danach auf <b>Position bestätigen</b>.
                        </p>
                    </div>
                </div>
            `,

            buttons: [
                {
                    action: "ok",
                    label: "Position bestätigen",
                    icon: "fas fa-check",
                    default: true,
                    callback: () => true
                },
                {
                    action: "cancel",
                    label: "Abbrechen",
                    icon: "fas fa-times",
                    callback: () => false
                }
            ],

            rejectClose: false
        });

    // +++ 9 - DIENERWAHL +++++++++++++++++++++++++++++++++++++++
    // Nur die in der Ahnengabe hinterlegten Diener.
    // Keine manuelle UUID- oder Akteurauswahl.

    const frageDiener = diener => {
        if (!diener.length) {
            ui.notifications.warn(
                "Luna sagt 🌙: In der Ahnengabe wurde kein verfügbarer Geisterdiener gefunden."
            );

            return null;
        }

        const optionen = diener
            .map(d => `<option value="${d.uuid}">${d.name}</option>`)
            .join("");

        return foundry.applications.api.DialogV2.wait({
            window: { title: "Geisterdiener wählen" },
            position: { width: 430 },

            content: `
                <form>
                    ${DSK_FW.UI.Header(vollerName, symbolPfad)}

                    <div class="dskbox2" style="margin-top:10px;">
                        <label style="font-weight:bold;font-size:.9em;">
                            In der Ahnengabe gefundene Diener:
                        </label>

                        <select
                            name="dienerSelect"
                            style="width:100%;padding:4px;margin-top:4px;"
                        >
                            ${optionen}
                        </select>
                    </div>
                </form>
            `,

            buttons: [
                {
                    action: "ok",
                    label: "Geist beschwören",
                    icon: "fas fa-ghost",
                    default: true,

                    callback: event => {
                        const form = event.target.closest("form");
                        if (!form) return null;

                        return String(
                            new FormData(form).get("dienerSelect") || ""
                        ).trim() || null;
                    }
                },
                {
                    action: "cancel",
                    label: "Abbrechen",
                    icon: "fas fa-times",
                    callback: () => null
                }
            ],

            rejectClose: false
        });
    };

    // +++ 10 - SCHÄDELSCHABLONE +++++++++++++++++++++++++++++++

    const erzeugeSchablone = async ({ x, y, casterUuid }) => {
        const docs = await canvas.scene.createEmbeddedDocuments("MeasuredTemplate", [{
            t: "circle", user: game.user.id, x, y, distance: 0.5, direction: 0, angle: 360,
            fillColor: game.user.color || "#76522d", fillAlpha: 0.15, lineThickness: 1, hidden: false,
            flags: { dsk: { geisterdienerSchaedel: true, casterUuid } }
        }]);

        return docs?.[0] || null;
    };

    // +++ 11 - DIENER-TOKEN ERZEUGEN ++++++++++++++++++++++++++

    const erzeugeDienerToken = async ({
        dienerActor,
        casterActor,
        casterToken,
        sessionId
    }) => {
        const spawnX = casterToken.document.x + canvas.grid.size;
        const spawnY = casterToken.document.y;

        const vorlage = await dienerActor.getTokenDocument({
            x: spawnX, y: spawnY,
            elevation: casterToken.document.elevation || 0,
            hidden: false, actorLink: false
        });

        if (!vorlage) {
            throw new Error("Die Tokenvorlage konnte nicht erzeugt werden.");
        }

        const data = vorlage.toObject();
        delete data._id;

        Object.assign(data, {
            x: spawnX, y: spawnY,
            elevation: casterToken.document.elevation || 0,
            hidden: false, actorId: dienerActor.id, actorLink: false
        });

        data.texture = foundry.utils.deepClone(data.texture || {});

        if (!String(data.texture.src || "").trim()) {
            data.texture.src = String(
                dienerActor.prototypeToken?.texture?.src ||
                dienerActor.img ||
                symbolPfad
            );
        }

        data.sight = foundry.utils.deepClone(
            casterToken.document.sight?.toObject?.() ||
            casterToken.document.sight ||
            {}
        );

        data.detectionModes = foundry.utils.deepClone(
            Array.from(casterToken.document.detectionModes || [])
                .map(modus =>
                    modus?.toObject?.() ||
                    foundry.utils.deepClone(modus)
                )
        );

        data.light = foundry.utils.deepClone(
            casterToken.document.light?.toObject?.() ||
            casterToken.document.light ||
            {}
        );

        data.disposition = casterToken.document.disposition;
        data.displayName = casterToken.document.displayName;
        data.displayBars = casterToken.document.displayBars;

        // Eigene Daten des unverknüpften Tokens.
        data.delta = foundry.utils.deepClone(data.delta || {});

        foundry.utils.setProperty(data, "flags.dsk.geisterdiener", true);
        foundry.utils.setProperty(data, "flags.dsk.spawnedByUuid", casterActor.uuid);
        foundry.utils.setProperty(data, "flags.dsk.geisterdienerSessionId", sessionId);

        foundry.utils.setProperty(data, "delta.flags.dsk.geisterdiener", true);
        foundry.utils.setProperty(data, "delta.flags.dsk.spawnedByUuid", casterActor.uuid);
        foundry.utils.setProperty(data, "delta.flags.dsk.geisterdienerSessionId", sessionId);

        const docs = await canvas.scene.createEmbeddedDocuments("Token", [data]);
        const token = docs?.[0] || null;

        if (!token?.actor) {
            if (token) {
                await canvas.scene
                    .deleteEmbeddedDocuments("Token", [token.id])
                    .catch(() => {});
            }

            throw new Error(
                "Der unverknüpfte Geisterdiener-Token konnte nicht erzeugt werden."
            );
        }

        await token.actor.update({
            "flags.dsk.geisterdiener": true,
            "flags.dsk.spawnedByUuid": casterActor.uuid,
            "flags.dsk.geisterdienerSessionId": sessionId
        }, {
            dskGeisterdienerSetup: true
        });

        return token;
    };

    // +++ 12 - BEREINIGUNG +++++++++++++++++++++++++++++++++++++

    const bereinige = async effect => {
        if (
            !effect ||
            !istAktiverGM() ||
            effect.getFlag("dsk", "isGeisterdiener") !== true
        ) {
            return false;
        }

        const scene =
            game.scenes.get(effect.getFlag("dsk", "sceneId")) ||
            canvas.scene;

        const tokenId = effect.getFlag("dsk", "dienerTokenId");
        const templateId = effect.getFlag("dsk", "schaedelTemplateId");
        const sessionId = effect.getFlag("dsk", "sessionId");

        if (scene?.tokens.get(tokenId)) {
            await scene.deleteEmbeddedDocuments(
                "Token",
                [tokenId],
                { dskGeisterdienerCleanup: true }
            );
        }

        if (scene?.templates.get(templateId)) {
            await scene.deleteEmbeddedDocuments(
                "MeasuredTemplate",
                [templateId],
                { dskGeisterdienerCleanup: true }
            );
        }

        const warnMessageId =
            effect.getFlag(
                "dsk",
                "reichweitenWarnungMessageId"
            );

        if (warnMessageId) {
            const warnMessage =
                game.messages.get(
                    warnMessageId
                );

            if (warnMessage) {
                await warnMessage
                    .delete()
                    .catch(() => {});
            }
        }

        const actor =
            await ladeActor(
                effect.getFlag(
                    "dsk",
                    "dienerActorUuid"
                )
            );

        if (actor && sessionId) {
            await entferneRechte({
                actor,
                sessionId
            });
        }

        return true;
    };

    // +++ 13 - WIRKUNGSENDE-HOOK +++++++++++++++++++++++++++++++

    if (globalThis._dskGeisterdienerDeleteEffectHook) {
        Hooks.off(
            "deleteActiveEffect",
            globalThis._dskGeisterdienerDeleteEffectHook
        );
    }

    globalThis._dskGeisterdienerDeleteEffectHook =
        Hooks.on("deleteActiveEffect", async effect => {
            try {
                await bereinige(effect);
            } catch (error) {
                console.error(
                    "Geisterdiener: Bereinigung fehlgeschlagen.",
                    error
                );
            }
        });

    // +++ 14 - REICHWEITENWÄCHTER ++++++++++++++++++++++++++++++

    if (globalThis._dskGeisterdienerReichweitenHook) {
        Hooks.off(
            "updateToken",
            globalThis._dskGeisterdienerReichweitenHook
        );
    }

    globalThis._dskGeisterdienerReichweitenHook =
        Hooks.on("updateToken", async (tokenDokument, change) => {
            if (
                !istAktiverGM() ||
                (
                    change.x === undefined &&
                    change.y === undefined
                )
            ) {
                return;
            }

            // Diener bewegt sich.
            if (
                tokenDokument.getFlag(
                    "dsk",
                    "geisterdiener"
                ) === true
            ) {
                const casterActor =
                    await ladeActor(
                        tokenDokument.getFlag(
                            "dsk",
                            "spawnedByUuid"
                        )
                    );

                const effekt =
                    findeHaupteffekt(
                        casterActor,
                        tokenDokument.getFlag(
                            "dsk",
                            "geisterdienerSessionId"
                        )
                    );

                if (effekt) {
                    await aktualisiereReichweitenWarnung({
                        effekt,
                        dienerToken: tokenDokument,
                        casterActor
                    });
                }

                return;
            }

            // Wirkender bewegt sich und trägt den Schädel.
            const casterActor = tokenDokument.actor;
            if (!casterActor) return;

            const effekte =
                casterActor.effects.filter(effect =>
                    effect.getFlag("dsk", "isGeisterdiener") === true &&
                    effect.getFlag("dsk", "modus") === "selbst" &&
                    effect.getFlag("dsk", "casterTokenId") === tokenDokument.id
                );

            for (const effekt of effekte) {
                const scene =
                    game.scenes.get(
                        effekt.getFlag(
                            "dsk",
                            "sceneId"
                        )
                    ) ||
                    canvas.scene;

                const dienerToken =
                    scene?.tokens.get(
                        effekt.getFlag(
                            "dsk",
                            "dienerTokenId"
                        )
                    );

                if (dienerToken) {
                    await aktualisiereReichweitenWarnung({
                        effekt,
                        dienerToken,
                        casterActor
                    });
                }
            }
        });

    // +++ 15 - DIENER GELÖSCHT +++++++++++++++++++++++++++++++++

    if (globalThis._dskGeisterdienerDeleteTokenHook) {
        Hooks.off(
            "deleteToken",
            globalThis._dskGeisterdienerDeleteTokenHook
        );
    }

    globalThis._dskGeisterdienerDeleteTokenHook =
        Hooks.on("deleteToken", async (token, options) => {
            if (
                !istAktiverGM() ||
                options?.dskGeisterdienerCleanup ||
                token.getFlag("dsk", "geisterdiener") !== true
            ) {
                return;
            }

            const casterActor =
                await ladeActor(
                    token.getFlag(
                        "dsk",
                        "spawnedByUuid"
                    )
                );

            const effect =
                findeHaupteffekt(
                    casterActor,
                    token.getFlag(
                        "dsk",
                        "geisterdienerSessionId"
                    )
                );

            if (effect) {
                await effect.delete();
            }
        });

    // +++ 16 - SCHÄDEL GELÖSCHT ++++++++++++++++++++++++++++++++

    if (globalThis._dskGeisterdienerDeleteTemplateHook) {
        Hooks.off(
            "deleteMeasuredTemplate",
            globalThis._dskGeisterdienerDeleteTemplateHook
        );
    }

    globalThis._dskGeisterdienerDeleteTemplateHook =
        Hooks.on("deleteMeasuredTemplate", async (template, options) => {
            if (
                !istAktiverGM() ||
                options?.dskGeisterdienerCleanup ||
                template.getFlag("dsk", "geisterdienerSchaedel") !== true
            ) {
                return;
            }

            const casterActor =
                await ladeActor(
                    template.getFlag(
                        "dsk",
                        "casterUuid"
                    )
                );

            const effect =
                findeHaupteffekt(
                    casterActor,
                    template.getFlag(
                        "dsk",
                        "sessionId"
                    )
                );

            if (effect) {
                await effect.delete();
            }
        });

    // +++ 17 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++

    const verarbeiteAnfrage = async (casterActor, daten) => {
        if (!casterActor || !daten || !istAktiverGM()) return false;

        if (
            daten.sceneId &&
            daten.sceneId !== canvas.scene?.id
        ) {
            ui.notifications.warn(
                `Luna sagt: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`
            );
            return false;
        }

        const casterToken =
            DSK_FW.Token.Finde(
                casterActor,
                daten.casterTokenId,
                daten.casterTokenUuid
            );

        if (!casterToken) {
            ui.notifications.warn(
                `Luna sagt: Der Token von „${casterActor.name}“ wurde nicht gefunden!`
            );
            return false;
        }

        if (findeHaupteffekt(casterActor)) {
            ui.notifications.warn(
                `Luna sagt: ${casterActor.name} besitzt bereits einen materialisierten Geisterdiener!`
            );
            return false;
        }

        const qs =
            Math.max(
                1,
                Math.floor(
                    Number(daten.qs) ||
                    1
                )
            );

        const casterName =
            daten.casterName ||
            DSK_FW.ResolveTokenName(
                casterActor
            );

        const sessionId =
            `geisterdiener-${Date.now()}-${foundry.utils.randomID()}`;

        let dienerActor = null;
        let dienerToken = null;
        let schablone = null;
        let hauptEffekt = null;

        try {
            console.info(
                "Geisterdiener: 1/5 Diener laden oder importieren."
            );

            dienerActor =
                await ladeOderImportiereDiener({
                    sourceUuid: daten.dienerUuid,
                    sourceName:
                        daten.dienerName ||
                        daten.dienerUuid
                });

            const userIds =
                new Set(
                    DSK_FW.Empfaenger.Besitzer(
                        casterActor
                    )
                );

            if (
                daten.requestedByUserId &&
                game.users.get(
                    daten.requestedByUserId
                )
            ) {
                userIds.add(
                    daten.requestedByUserId
                );
            }

            console.info(
                "Geisterdiener: 2/5 Rechte vergeben."
            );

            await fuegeRechteHinzu({
                actor: dienerActor,
                sessionId,
                userIds: [...userIds]
            });

            let skullX =
                Number(
                    casterToken.center.x
                );

            let skullY =
                Number(
                    casterToken.center.y
                );

            if (
                daten.modus ===
                "ort"
            ) {
                schablone =
                    canvas.scene.templates.get(
                        daten.schaedelTemplateId
                    ) ||
                    null;

                if (!schablone) {
                    throw new Error(
                        "Die bestätigte Schädel-Schablone wurde nicht gefunden."
                    );
                }

                skullX =
                    Number(
                        schablone.x
                    );

                skullY =
                    Number(
                        schablone.y
                    );

                await schablone.update({
                    "flags.dsk.geisterdienerSchaedel": true,
                    "flags.dsk.casterUuid": casterActor.uuid,
                    "flags.dsk.sessionId": sessionId
                });
            }

            console.info(
                "Geisterdiener: 3/5 Token neben dem Wirkenden erzeugen."
            );

            dienerToken =
                await erzeugeDienerToken({
                    dienerActor,
                    casterActor,
                    casterToken,
                    sessionId
                });

            if (
                !canvas.scene.tokens.get(
                    dienerToken.id
                )
            ) {
                throw new Error(
                    "Der erzeugte Diener-Token ist nicht auf der Szene vorhanden."
                );
            }

            console.info(
                "Geisterdiener: Token erzeugt.",
                dienerToken.uuid
            );

            console.info(
                "Geisterdiener: 4/5 Haupteffekt anlegen."
            );

            hauptEffekt =
                await DSK_FW.Effekt.Anwenden({
                    name: vollerName,
                    ahne,

                    beschreibung:
                        `${basisBeschreibung}` +
                        `<br><br><b>Beschworener Diener:</b> ${dienerActor.name}` +
                        `<br><b>Schädel:</b> ${
                            daten.modus === "selbst"
                                ? "Beim Wirkenden"
                                : "An einem bestätigten Ort"
                        }` +
                        `<br><b>Maximaler Abstand:</b> ${radiusSchritt} Schritt` +
                        `<br><b>Wirkungsdauer:</b> ${qs * 5} Minuten`,

                    gabeZiel: "",
                    qs,
                    ziel: casterActor,
                    showIcon: 1,

                    flags: {
                        dsk: {
                            isGeisterdiener: true,
                            casterUuid: casterActor.uuid,
                            qs,
                            radiusSchritt,
                            modus: daten.modus,
                            sceneId: canvas.scene.id,
                            casterTokenUuid: casterToken.document.uuid,
                            casterTokenId: casterToken.id,
                            dienerActorUuid: dienerActor.uuid,
                            dienerTokenUuid: dienerToken.uuid,
                            dienerTokenId: dienerToken.id,
                            schaedelTemplateId:
                                daten.modus === "ort"
                                    ? schablone?.id || null
                                    : null,
                            skullX,
                            skullY,
                            sessionId
                        }
                    }
                });

            if (!hauptEffekt) {
                throw new Error(
                    "Der Haupteffekt konnte nicht angelegt werden."
                );
            }

            console.info(
                "Geisterdiener: 5/5 Dienereffekt und Karte ergänzen."
            );

            try {
                await DSK_FW.Effekt.Anwenden({
                    name:
                        `${vollerName} – Diener von ${casterName}`,

                    ahne,

                    beschreibung:
                        `Dieser Diener ist materialisiert und an den Schädel von ` +
                        `<b>${casterName}</b> gebunden.`,

                    gabeZiel: "",
                    qs,
                    ziel: dienerToken.actor,
                    showIcon: 1,

                    flags: {
                        dsk: {
                            isGeisterdienerToken: true,
                            casterUuid: casterActor.uuid,
                            sessionId
                        }
                    }
                });
            } catch (folgeFehler) {
                console.warn(
                    "Geisterdiener: Dienereffekt konnte nicht ergänzt werden; der beschworene Token bleibt bestehen.",
                    folgeFehler
                );
            }

                        try {
                await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
                    messageId: daten.messageId,
                    gabenName: vollerName,
                    ahne,
                    beschreibung: basisBeschreibung,
                    wirkender: casterName,

                    ziele: [{
                        name: dienerActor.name,
                        rolle: "Materialisierter Geisterdiener"
                    }],

                    misserfolge: [],
                    dauerText: `${qs * 5} Minuten (${qs} QS × 5 Min.)`,
                    erfolgreich: true
                });
            } catch (folgeFehler) {
                console.warn(
                    "Geisterdiener: Wirkungskarte konnte nicht aktualisiert werden; der beschworene Token bleibt bestehen.",
                    folgeFehler
                );
            }

            ui.notifications.info(
                `Luna sagt 🌙: ${dienerActor.name} wurde neben ${casterName} beschworen.`
            );

            return true;

        } catch (error) {
            console.error(
                "Geisterdiener: Beschwörung fehlgeschlagen.",
                error
            );

            const tokenSteht =
                Boolean(
                    dienerToken &&
                    canvas.scene?.tokens.get(
                        dienerToken.id
                    )
                );

            if (tokenSteht) {
                ui.notifications.warn(
                    `Luna sagt 🌙: ${dienerActor?.name || "Der Geisterdiener"} wurde auf der Szene erzeugt, aber ein nachfolgender Schritt ist fehlgeschlagen. Der Token bleibt zur Prüfung bestehen.`
                );

                return true;
            }

            if (
                schablone &&
                canvas.scene?.templates.get(
                    schablone.id
                )
            ) {
                await canvas.scene.deleteEmbeddedDocuments(
                    "MeasuredTemplate",
                    [schablone.id],
                    {
                        dskGeisterdienerCleanup: true
                    }
                ).catch(() => {});
            }

            if (dienerActor) {
                await entferneRechte({
                    actor: dienerActor,
                    sessionId
                }).catch(() => {});
            }

            ui.notifications.error(
                `Luna sagt 🌙: Die Beschwörung scheiterte vor der Tokenanlage: ${error?.message || error}`
            );

            return true;
        }
    };

    // +++ 18 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++

    if (game.user.isGM) {
        const anfragen =
            DSK_FW.GMAnfrage.Finden(
                flagKey
            );

        if (anfragen.length) {
            for (
                const actor
                of anfragen
            ) {
                const daten =
                    DSK_FW.GMAnfrage.Lesen(
                        actor,
                        flagKey
                    );

                if (
                    daten &&
                    await verarbeiteAnfrage(
                        actor,
                        daten
                    )
                ) {
                    await DSK_FW.GMAnfrage.Loeschen(
                        actor,
                        flagKey
                    );
                }
            }

            return;
        }
    }

    // +++ 19 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++

    let casterActor =
        canvas.tokens.controlled[0]?.actor ||
        game.user.character ||
        null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables
                .map(token => token.actor)
                .find(actor =>
                    actor?.getFlag(
                        "world",
                        "letzteGabenQS"
                    ) !== undefined
                ) ||

            game.actors.find(actor =>
                actor.getFlag(
                    "world",
                    "letzteGabenQS"
                ) !== undefined
            ) ||

            null;
    }

    if (!casterActor) {
        return ui.notifications.warn(
            "Luna sagt: Bitte wähle zuerst deinen Token aus!"
        );
    }

    if (
        !game.user.isGM &&
        !casterActor.isOwner
    ) {
        return ui.notifications.warn(
            "Luna sagt: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
        );
    }

    const casterToken =
        DSK_FW.Token.Finde(
            casterActor
        );

    if (!casterToken) {
        return ui.notifications.warn(
            "Luna sagt: Der Wirkende braucht einen Token auf der aktuellen Szene!"
        );
    }

    const casterName =
        DSK_FW.ResolveTokenName(
            casterActor
        );

    if (
        findeHaupteffekt(
            casterActor
        )
    ) {
        return ui.notifications.warn(
            `Luna sagt: ${casterName} besitzt bereits einen materialisierten Geisterdiener!`
        );
    }

    const qs =
        DSK_FW.QS.Ermitteln({
            actor: casterActor,
            gabenName,

            suchbegriffe: [
                "Geisterdiener Probe",
                "Geisterdiener"
            ],

            testDataObj:
                typeof testData !== "undefined"
                    ? testData
                    : null,

            fallback: 0,
            protokollieren: true
        });

    if (qs <= 0) {
        return ui.notifications.warn(
            "Luna sagt: Die Probe ist fehlgeschlagen oder die Qualitätsstufe konnte nicht ermittelt werden!"
        );
    }

    // +++ 20 - SCHÄDELMODUS ++++++++++++++++++++++++++++++++++++

    const modus =
        await frageSchaedelmodus();

    // Abbrechen = stilles Ende.
    if (!modus) {
        await raeumeQSAuf(
            casterActor
        );

        return;
    }

    let aktuelleSchablone =
        null;

    let skullX =
        Number(
            casterToken.center.x
        );

    let skullY =
        Number(
            casterToken.center.y
        );

    if (modus === "ort") {
        const schablone =
            await erzeugeSchablone({
                x: casterToken.center.x,
                y: casterToken.center.y,
                casterUuid: casterActor.uuid
            });

        if (!schablone) {
            await raeumeQSAuf(
                casterActor
            );

            return ui.notifications.error(
                "Luna sagt: Der Schädelkreis konnte nicht erzeugt werden!"
            );
        }

        try {
            canvas.templates.activate();
        } catch (error) {}

        const positionBestaetigt =
            await bestaetigeSchaedelposition();

        try {
            canvas.tokens.activate();
        } catch (error) {}

        // Abbrechen = Schablone löschen und still beenden.
        if (!positionBestaetigt) {
            if (
                canvas.scene.templates.get(
                    schablone.id
                )
            ) {
                await canvas.scene.deleteEmbeddedDocuments(
                    "MeasuredTemplate",
                    [schablone.id]
                ).catch(() => {});
            }

            await raeumeQSAuf(
                casterActor
            );

            return;
        }

        aktuelleSchablone =
            canvas.scene.templates.get(
                schablone.id
            );

        if (!aktuelleSchablone) {
            await raeumeQSAuf(
                casterActor
            );

            return ui.notifications.error(
                "Luna sagt: Der bestätigte Schädelkreis wurde nicht gefunden!"
            );
        }

        skullX =
            Number(
                aktuelleSchablone.x
            );

        skullY =
            Number(
                aktuelleSchablone.y
            );
    }

    // +++ 21 - DIENER AUSWÄHLEN ++++++++++++++++++++++++++++++++

    const dynamischeDiener =
        await findeDienerAusAhnengabe(
            casterActor
        );

    const dienerUuid =
        await frageDiener(
            dynamischeDiener
        );

    // Abbrechen = ggf. Schablone entfernen und still beenden.
    if (!dienerUuid) {
        if (
            aktuelleSchablone &&
            canvas.scene.templates.get(
                aktuelleSchablone.id
            )
        ) {
            await canvas.scene.deleteEmbeddedDocuments(
                "MeasuredTemplate",
                [aktuelleSchablone.id]
            ).catch(() => {});
        }

        await raeumeQSAuf(
            casterActor
        );

        return;
    }

    const eintrag =
        dynamischeDiener.find(
            diener =>
                diener.uuid ===
                dienerUuid
        );

    const dauerText =
        `${qs * 5} Minuten (${qs} QS × 5 Min.)`;

    // +++ 22 - GEMEINSAME GABENKARTE + ROTER GM-BUTTON ++++++++++++

const gmLink = DSK_FW.GabenUI.GMMakroButton(
    macroUuid,
    "Geisterdiener materialisieren",
    "Das Makro muss durch die Spielleitung ausgeführt werden."
);

const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
    gabenName: vollerName, ahne,
    beschreibung:
        `${basisBeschreibung}` +
        `<br><br><b>Schädel:</b> ${modus === "selbst" ? "Beim Wirkenden" : "An einem bestätigten Ort"}`,
    wirkender: casterName,
    ziele: [{
        name: eintrag?.name || dienerUuid,
        rolle: "Ausgewählter Geisterdiener"
    }],
    misserfolge: [], dauerText, gmLink,
    gmBereich: !game.user.isGM,
    anfragenderUserId: game.user.id
});

if (!nachricht) {
    if (aktuelleSchablone && canvas.scene.templates.get(aktuelleSchablone.id)) {
        await canvas.scene.deleteEmbeddedDocuments("MeasuredTemplate", [aktuelleSchablone.id]).catch(() => {});
    }

    await raeumeQSAuf(casterActor);
    return ui.notifications.error("Luna sagt: Die Wirkungskarte konnte nicht erstellt werden!");
}

    // +++ 23 - ANFRAGEDATEN +++++++++++++++++++++++++++++++++++++

    const daten = {
        casterUuid: casterActor.uuid,
        casterName,

        casterTokenId: casterToken.id,
        casterTokenUuid:
            casterToken.document?.uuid ||
            casterToken.uuid ||
            null,

        qs,
        modus,
        skullX,
        skullY,

        schaedelTemplateId:
            aktuelleSchablone?.id ||
            null,

        dienerUuid,

        dienerName:
            eintrag?.name ||
            dienerUuid,

        sceneId:
            canvas.scene?.id ||
            null,

        requestedByUserId:
            game.user.id,

        messageId:
            nachricht.id,

        macroUuid
    };

    // +++ 24 - GM DIREKT ODER ANFRAGE SPEICHERN ++++++++++++++++

    if (game.user.isGM) {
        await verarbeiteAnfrage(
            casterActor,
            daten
        );

        await raeumeQSAuf(
            casterActor
        );

        return;
    }

    await DSK_FW.GMAnfrage.Speichern(
        casterActor,
        flagKey,
        daten
    );

    // +++ 25 - QS AUFRÄUMEN +++++++++++++++++++++++++++++++++++++

    await raeumeQSAuf(
        casterActor
    );

    ui.notifications.info(
        "Luna sagt: Die Materialisierung des Geisterdieners wurde bei der Spielleitung beantragt."
    );

}).call(this);
